CustomField.formula:
/* 総労働時間 */
LEFT(TEXT(TotalWorkTime__c*100),LEN(TEXT(TotalWorkTime__c*100))-2) & '.' & RIGHT(TEXT(TotalWorkTime__c*100),2) &
/* 記号 */
IF(Overtime__c>0,'(+',IF(Overtime__c<0,'(','')) &
/* 残業不足時間 */
IF(Overtime__c==0,'',
  LEFT(TEXT(Overtime__c*100),LEN(TEXT(Overtime__c*100))-2) & '.' & RIGHT(TEXT(Overtime__c*100),2) & ')'
)
